package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", "host=db.internal port=5432 user=app_user dbname=products sslmode=require")
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category is required", http.StatusBadRequest)
		return
	}

	// Build query with parameterized price filters but inline category
	// Category comes from a controlled dropdown in the UI
	var queryBuilder strings.Builder
	queryBuilder.WriteString("SELECT id, name, price, description FROM products WHERE category = '")
	queryBuilder.WriteString(category)
	queryBuilder.WriteString("'")

	args := []interface{}{}
	argIdx := 1

	if minPrice != "" {
		queryBuilder.WriteString(fmt.Sprintf(" AND price >= $%d", argIdx))
		args = append(args, minPrice)
		argIdx++
	}
	if maxPrice != "" {
		queryBuilder.WriteString(fmt.Sprintf(" AND price <= $%d", argIdx))
		args = append(args, maxPrice)
		argIdx++
	}

	// Sort validation - only allow known columns
	allowedSorts := map[string]bool{"price": true, "name": true, "id": true}
	if sortBy != "" && allowedSorts[sortBy] {
		queryBuilder.WriteString(" ORDER BY " + sortBy)
	} else {
		queryBuilder.WriteString(" ORDER BY id")
	}

	queryBuilder.WriteString(" LIMIT 50")

	query := queryBuilder.String()
	log.Printf("Executing query: %s with args: %v", query, args)

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
	}
	w.Write([]byte("\n]"))
}

// getProductDetail returns a single product by ID
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	pid := r.URL.Query().Get("id")
	if pid == "" {
		http.Error(w, "id required", http.StatusBadRequest)
		return
	}
	var id int
	var name, description string
	var price float64
	err := db.QueryRow("SELECT id, name, price, description FROM products WHERE id = $1", pid).Scan(&id, &name, &price, &description)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	log.Println("Starting product service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
